def median(xs: list[float]) -> float:
    if not xs:
        raise ValueError('empty')
    s = sorted(xs)
    n = len(s)
    if n % 2:
        return float(s[n // 2])
    return (s[n // 2 - 1] + s[n // 2]) / 2

def clamp(x: int, lo: int, hi: int) -> int:
    if lo > hi:
        raise ValueError('lo > hi')
    return lo if x < lo else hi if x > hi else x

def safe_div(a: float, b: float) -> float:
    if b == 0:
        raise ZeroDivisionError('division by zero')
    return a / b

def dedupe(xs: list[int]) -> list[int]:
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def truncate(s: str, n: int) -> str:
    if n < 0:
        raise ValueError('n must be >= 0')
    if len(s) <= n:
        return s
    if n == 0:
        return ''
    return s[: n - 1] + '…'

import math


def round_half(x: float) -> int:
    if math.isnan(x) or math.isinf(x):
        raise ValueError('cannot round')
    fl = math.floor(x)
    frac = x - fl
    if frac > 0.5:
        return int(fl) + 1
    if frac < 0.5:
        return int(fl)
    return int(fl) + 1 if x > 0 else int(fl)  # ties away from zero

def percentile(xs: list[float], p: float) -> float:
    if not xs:
        raise ValueError('empty')
    if not 0 <= p <= 100:
        raise ValueError('p out of range')
    s = sorted(xs)
    if len(s) == 1:
        return float(s[0])
    k = (len(s) - 1) * p / 100.0
    f = int(k)
    c = min(f + 1, len(s) - 1)
    return s[f] + (s[c] - s[f]) * (k - f)

def parse_bool(s: str) -> bool:
    t = s.strip().lower()
    if t in ('true', '1', 'yes', 'y', 'on'):
        return True
    if t in ('false', '0', 'no', 'n', 'off'):
        return False
    raise ValueError('not a boolean: ' + s)

def chunk(xs: list[int], n: int) -> list[list[int]]:
    if n <= 0:
        raise ValueError('n must be positive')
    return [xs[i:i + n] for i in range(0, len(xs), n)]
